/** Everything the markup binds to, for one position in the loop. */
export function values(p) {
  // p is the argument.
  function lin(k) {
    if (p <= k[0][0]) return k[0][1];
    for (var i = 1; i < k.length; i++) if (p <= k[i][0]) { var a = k[i-1], b = k[i], f = (p - a[0]) / (b[0] - a[0]); f = 1 - Math.pow(1 - f, 3); return a[1] + (b[1] - a[1]) * f; }
    return k[k.length-1][1];
  }
  var out = p < 94 ? 1 : Math.max(0, 1 - (p - 94) / 6);
  var v = {};
  function phases(ph) { for (var i = 0; i < ph.length; i++) { v['on'+i] = (p >= ph[i][0] && p < ph[i][1]) ? 1 : 0; v['done'+i] = (p >= ph[i][1] && p < 97) ? out : 0; } }

  phases([[0,14],[14,34],[34,58],[58,80]]);
  v.col = lin([[1,0],[6,1]]) * out; v.nc = Math.round(20 * lin([[1,0],[10,1]]));
  v.gu = (p >= 15 && p < 40) ? lin([[15,0],[20,1]]) : (p >= 40 ? Math.max(0, 1 - (p - 40) / 4) : 0);
  v.sn = (p >= 24 && p < 97) ? out : 0;
  var ng = 0;
  for (var i = 0; i < 6; i++) { v['gx'+i] = lin([[35 + i * 2, 0],[37 + i * 2, 1]]) * out; if (p >= 36 + i * 2) ng++; }
  for (var j = 0; j < 4; j++) { v['gy'+j] = lin([[47 + j * 2, 0],[49 + j * 2, 1]]) * out; if (p >= 48 + j * 2) ng++; }
  v.ng = ng;
  v.dm = lin([[59,0],[65,1]]) * out;
  for (var k = 0; k < 5; k++) v['l'+k] = p >= 66 + k * 2 ? out : 0.25 * out;
  v.fin = (p >= 76 && p < 97) ? out : 0;

  return { v: v };}

const card = { id, title, width, height, loopMs, attrs, stage, markup, values };
export default card;
